/* Current Video 4 Figma layouts; all amounts and actions retain the shared model. */
(()=>{
 const assets={steak:'b887a.png',chicken:'5c26b.png',ribs:'57223.png',shrimp:'8baeb.png',lamb:'3a1e6.png',salmon:'41539.png',garlic:'a7f33.png',peppers:'7460b.png'};
 const empty=(title,text)=>'<div class="v4-empty" role="status"><h3>'+title+'</h3><p>'+text+'</p></div>';
 const prior={order:posOrderPage,checkout:posCheckoutPage,list:posReservations,checkin:checkinPage,tables:connectedTables,handle};
 posFooter=function(){const current=state.ui.admin,active=current==='pos-arrival'?4:current==='pos-completed'?2:1;return '<nav class="pos-bottom" aria-label="Cashier navigation">'+[['Availability Grid','cx-pos-availability','b8134.svg'],['Reservations','cx-pos',active===1?'ff087.svg':'45ba5.svg'],['Completed','cx-pos-completed','51041.svg'],['Invoices','cx-pos-invoices','866bc.svg'],['Check-in','cx-pos-scan',active===4?'71674.svg':'63d81.svg'],['Settings','cx-pos-settings','09e53.svg']].map(([title,action,asset],i)=>button('<span class="v4-nav-icon" aria-hidden="true">'+img(asset)+'</span>'+title,action,i===active?'active':'')).join('')+'</nav>';};
 posOrderPage=function(){let html=prior.order();
  for(const [id,asset] of Object.entries(assets))html=html.replace('<button data-action="cx-item-'+id+'">','<button class="v4-product-photo" data-action="cx-item-'+id+'">'+img(asset,''));
  html=html.replace(/<small>\$[\d,.]+<\/small>/g,'');
  html=html.replace('<input name="pos-item-search" class="pos-item-search" placeholder="Search menu">','<div class="v4-menu-search"><input name="pos-item-search" class="pos-item-search" placeholder="Search menu" aria-label="Search menu" hidden>'+button(img('fd3ca.svg','Search menu'),'v4-menu-search','v4-search-toggle')+'</div>');
  html=html.replace('<div class="pos-cart-lines">','<div class="pos-cart-lines">'+(!ops().cart.length?empty('No additional charges','Select an item to start this order.'):'')).replace('<div class="pos-order-actions">',empty('No items found','Try another search or category.').replace('class="v4-empty"','class="v4-empty v4-menu-empty" hidden')+'<div class="pos-order-actions">');
  ['#0eabd1','#ce2a51','#12af4d','#f48843','#15c6af','#f8bd3d','#e944da','#8055ff'].forEach((old,i)=>html=html.replaceAll(old,['#12a9e0','#d32f4c','#16b04a','#f4874b','#1ecdb0','#f6b93b','#f052d8','#7c5cff'][i]));return html;
 };
 posCheckoutPage=function(){const r=activePosGuest();return prior.checkout().replace(button('Charge to room','cx-charge-room','primary wide-btn')+'<p class="hint">'+esc(v2Full(r.guest))+' · Res #'+r.id+'</p>',button('Charge to room<small>'+esc(v2Full(r.guest))+' · Res #'+r.id+'</small>','cx-charge-room','primary wide-btn v4-room-pay'));};
 posReservations=function(){const completed=state.ui.admin==='pos-completed';return prior.list().replace('<option value="guest">','<option value="guest" '+(ops().sort==='guest'?'selected':'')+'>').replace('</tbody></table></div>','</tbody></table></div>'+empty(completed?'No completed stays':'No reservations found',completed?'Checked-out stays will appear here.':'Try another guest, room or reservation number.').replace('class="v4-empty"','class="v4-empty v4-list-empty" '+(connectedGuests().some(r=>r.paid&&(completed?r.checkedOut:!r.checkedOut))?'hidden':'')));};
 checkinPage=function(){return prior.checkin().replace('Search reservation ⌕','Search reservation'+img('9325b.svg','')).replace('<span class="checkin-success" aria-label="Success">✓</span>','<span class="checkin-success v4-check-success" aria-label="Success">'+img('177c5.svg','')+img('ecea0.svg','Checked in')+'</span>').replace('class="v4-find-result"','class="v4-find-result" hidden').replace('<div class="v4-find-results">','<div class="v4-find-results"><p class="v4-match-count" hidden></p>');};
 const folioLine=(label,amount,sub='')=>'<div class="v4-folio-line"><div>'+label+(sub?'<small>'+sub+'</small>':'')+'</div><strong>'+amount+'</strong></div>';
 checkOutPage=function(){const r=activePosGuest(),balance=stayBalance(r),orders=ordersFor(r);return posShell('Check-out · #'+r.id,'<div class="v4-departure"><header><div><h2>'+esc(v2Full(r.guest))+' ('+esc(state.request.organization)+')</h2><p>'+esc(r.unit)+' · '+dates()+'</p></div><span class="pos-chip">'+(r.checkedOut?'Checked out':'Checked in')+'</span></header><div class="v4-folio-columns"><section><h3>Folio</h3>'+folioLine('Room · '+esc(r.type)+' ('+nights()+' nights)',money(roomRate(r.type)*nights()),money(roomRate(r.type))+' × '+nights()+' nights')+folioLine('Tax on room (10%)',money(r.amount-roomRate(r.type)*nights()))+orders.map(o=>folioLine(esc(o.id+' · '+o.items.map(x=>x.title).join(', ')),money(o.subtotal-o.discount),esc(o.status+' · '+o.when))+folioLine('Tax on POS order (10%)',money(o.tax))+(o.tip?folioLine('Tip',money(o.tip)):'')).join('')+(extrasTotal(r)?folioLine('Additional charges',money(extrasTotal(r))):'')+(serviceTotal(r)?folioLine('Services',money(serviceTotal(r))):'')+folioLine('Payments received','− '+money(stayPaid(r)),r.organizerPaid?'Paid by organizer':'Card ending 4242')+'<div class="v4-folio-balance"><h2>Balance due</h2><strong>'+money(balance)+'</strong></div></section><aside><div><h3>'+(r.checkedOut?'Stay completed':'Pay the balance')+'</h3>'+(r.checkedOut?empty('Checked out','The final invoice is paid and the stay is checked out.') :button((balance?'Card<small>Pay '+money(balance)+'</small>':'Confirm check-out'),'cx-checkout-pay','primary v4-room-pay')+(balance?button('Cash','v4-checkout-cash'):'') )+button('Print invoice','cx-print-stay')+'</div>'+button(r.checkedOut?'Open reservation':'Open reservation folio','v2-record-'+r.id,'v4-folio-open')+'</aside></div></div>');};
 connectedTables=function(r){let html=prior.tables(r);if(!ordersFor(r).length)html=html.replace('</tbody>','<tr><td colspan="7">'+empty('No POS orders yet','Orders charged to this room will appear here.')+'</td></tr></tbody>');if(!requestsFor(r).length){const start=html.indexOf('Services (0)');html=html.slice(0,start)+html.slice(start).replace('</tbody>','<tr><td colspan="6">'+empty('No services requested','Guest service requests will appear here.')+'</td></tr></tbody>');}return html;};
 handle=function(a,el){if(a==='v4-menu-search'){const input=$('.pos-item-search');input.hidden=!input.hidden;if(!input.hidden)input.focus();return;}if(a==='v4-checkout-cash'){prior.handle('cx-checkout-pay',el);const select=$('#cx-pay-form select');if(select){select.value='Cash';select.dispatchEvent(new Event('change',{bubbles:true}));}return;}if(a==='cx-print-stay'){downloadBlob('Reservation #'+activePosGuest().id+'\nBalance due: '+money(stayBalance(activePosGuest())),'text/plain','Invoice_'+activePosGuest().id+'.txt');return;}return prior.handle(a,el);};
 document.addEventListener('input',e=>{if(e.target.name==='pos-search'){const visible=[...document.querySelectorAll('.pos-reservation')].some(x=>!x.hidden);$('.v4-list-empty').hidden=visible;}if(e.target.name==='pos-item-search'){const visible=[...document.querySelectorAll('.pos-item-grid button')].some(x=>!x.hidden);$('.v4-menu-empty').hidden=visible;}if(e.target.name==='v4-find'){const q=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('.v4-find-result').forEach(row=>{row.hidden=!q||!row.textContent.toLowerCase().includes(q);if(!row.hidden)count++;});$('.v4-no-results').hidden=!q||count>0;const label=$('.v4-match-count');label.hidden=!count;label.textContent=count+' '+(count===1?'match':'matches');}});
 render();
})();
